/* Focus practice: after a difficult conversation. Notes remain on screen only. */
practices.flagship={symbol:'✦',title:'После трудного разговора',duration:'4–6 минут',desc:'Вернуться к опоре, отделить событие от мыслей и выбрать свой следующий шаг.',text:'Небольшая самостоятельная практика после неприятного разговора.',kind:'guided',topic:'work'};
const priorOpenPractice=openPractice;
openPractice=function(key){if(key==='flagship'){launchFlagship();return}priorOpenPractice(key)};
const priorChooseSupport=chooseSupport;
chooseSupport=function(mood,cause,need){const list=priorChooseSupport(mood,cause,need);if(/началь|работ|коллег|шеф|разговор|конфликт/i.test(cause)&&need!=='rest')return [['После трудного разговора · 4–6 минут','practice:flagship'],...list.slice(0,3)];return list};
const featuredPractice=document.createElement('article');featuredPractice.className='focus-feature';featuredPractice.innerHTML='<div><span class="focus-kicker">ПРАКТИКА В ФОКУСЕ · 4–6 МИНУТ</span><h2>После трудного разговора</h2><p>Когда слова ещё звучат в голове. Сначала найдём опору, затем разберём событие и выберем один посильный шаг.</p><div class="focus-steps"><span>01 · Опора</span><span>02 · Ясность</span><span>03 · Действие</span></div></div>';
const featuredStart=document.createElement('button');featuredStart.className='focus-start';featuredStart.textContent='Попробовать практику →';featuredStart.onclick=()=>openPractice('flagship');featuredPractice.append(featuredStart);
document.querySelector('#library').insertBefore(featuredPractice,libraryToolbar);renderCatalog();
const todayFocus=document.createElement('button');todayFocus.className='today-focus';todayFocus.innerHTML='<span>✦ ПРАКТИКА ДНЯ</span><strong>После трудного разговора</strong><small>4–6 минут · пройти →</small>';todayFocus.onclick=()=>openPractice('flagship');document.querySelector('#today .right').append(todayFocus);
const focusOverlay=document.createElement('div');focusOverlay.id='focusOverlay';focusOverlay.className='focus-overlay';focusOverlay.setAttribute('role','dialog');focusOverlay.setAttribute('aria-modal','true');focusOverlay.setAttribute('aria-label','Практика после трудного разговора');focusOverlay.hidden=true;document.body.append(focusOverlay);
let focus=null,focusLast=null,focusTimer=null;
const focusActions={pause:{title:'Дать себе паузу',detail:'«Я вернусь к разговору позже. Сейчас мне нужно немного времени».',hint:'Можно ничего не отправлять прямо сейчас. Назначь момент, когда снова посмотришь на ситуацию.'},clarify:{title:'Уточнить задачу',detail:'«Помоги понять: какой результат ожидается и к какому сроку?»',hint:'Этот вариант подходит, если за неприятным тоном была конкретная рабочая задача.'},boundary:{title:'Обозначить границу',detail:'«Мне важно обсудить вопрос, когда мы можем говорить спокойно».',hint:'Подстрой слова под себя. Ты выбираешь время и безопасный способ разговора.'},support:{title:'Попросить поддержки',detail:'«У меня был трудный разговор. Можешь немного побыть со мной на связи?»',hint:'Поддержка может быть короткой: сообщение, звонок или совместная прогулка.'}};
function launchFlagship(){focusLast=document.activeElement;focus={step:0,source:'',before:0,after:0,noticed:[],fact:'',thought:'',action:'',completed:false};focusOverlay.hidden=false;document.body.classList.add('focus-open');renderFlagship();focusOverlay.querySelector('button')?.focus()}
function closeFlagship(){if(focusTimer){clearInterval(focusTimer);focusTimer=null}focusOverlay.hidden=true;document.body.classList.remove('focus-open');focusLast?.focus();focus=null}
function fButton(label,fn,cls='focus-button'){const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=label;b.onclick=fn;return b}
function renderFlagship(){if(!focus)return;const s=focus;focusOverlay.replaceChildren();const panel=document.createElement('div');panel.className='focus-panel';const top=document.createElement('div');top.className='focus-top';top.innerHTML='<span class="focus-brand">✦ РЯДОМ · ПРАКТИКА</span><span class="focus-progress-text"></span>';top.querySelector('.focus-progress-text').textContent=s.completed?'Готово':`Шаг ${Math.min(s.step+1,4)} из 4`;top.append(fButton('Закрыть',closeFlagship,'focus-close'));panel.append(top);const progress=document.createElement('div');progress.className='focus-progress';const fill=document.createElement('span');fill.style.width=(s.completed?100:(s.step+1)*25)+'%';progress.append(fill);panel.append(progress);const body=document.createElement('div');body.className='focus-body';panel.append(body);
const eyebrow=(text)=>{let x=document.createElement('span');x.className='focus-eyebrow';x.textContent=text;body.append(x)};
const heading=(title,copy)=>{let h=document.createElement('h2');h.textContent=title;let p=document.createElement('p');p.className='focus-intro';p.textContent=copy;body.append(h,p)};
const footer=document.createElement('div');footer.className='focus-footer';panel.append(footer);
if(s.completed){eyebrow('ТВОЙ МАЛЕНЬКИЙ ШАГ');heading('Можно остановиться здесь','Состояние замечено, действие выбрано. Не нужно заставлять себя чувствовать лучше.');let recap=document.createElement('div');recap.className='focus-recap';recap.innerHTML='<span>ЧТО ВЫБРАНО</span><strong></strong><p></p>';recap.querySelector('strong').textContent=focusActions[s.action]?.title||'Пауза';recap.querySelector('p').textContent=focusActions[s.action]?.detail||'';body.append(recap);let outcome=document.createElement('p');outcome.className='focus-outcome';outcome.textContent=s.before<1||s.after<0?'Результат не оценён. Это тоже нормально.':s.after<s.before?'Отмечено небольшое облегчение.':s.after>s.before?'Стало тяжелее. Эту практику можно оставить и обратиться к человеку, которому доверяешь.':'Состояние пока не изменилось. Ты всё равно можешь остановиться или выбрать поддержку.';body.append(outcome);let privacy=document.createElement('p');privacy.className='focus-privacy';privacy.textContent='В дневник сохранены только тема, выбранный шаг и твоя оценка результата. Написанные тобой фразы не сохранялись.';body.append(privacy);footer.append(fButton('Вернуться в приложение',closeFlagship,'focus-main'));}
else if(s.step===0){eyebrow('ПЕРЕД НАЧАЛОМ');heading('Что осталось после разговора?','Нам не нужно сейчас разбирать всё сразу. Отметь, с кем был разговор и насколько сильно он задел тебя в данный момент.');const source=document.createElement('div');source.className='focus-options';[['work','На работе'],['close','С близким'],['other','В другой ситуации']].forEach(([v,l])=>{let b=fButton(l,()=>{s.source=v;renderFlagship()},'focus-option'+(s.source===v?' selected':''));source.append(b)});body.append(source);let q=document.createElement('h3');q.textContent='Насколько сильно задело сейчас?';body.append(q);let scale=document.createElement('div');scale.className='focus-scale';[1,2,3,4].forEach(n=>scale.append(fButton(String(n),()=>{s.before=n;renderFlagship()},'focus-scale-button'+(s.before===n?' selected':''))));body.append(scale);let labels=document.createElement('div');labels.className='focus-scale-labels';labels.innerHTML='<span>Немного</span><span>Очень сильно</span>';body.append(labels);let note=document.createElement('p');note.className='focus-privacy';note.textContent='Если сейчас небезопасно или ситуация продолжается, сначала позаботься о своей безопасности и обратись к человеку рядом. Практику можно закрыть в любой момент.';body.append(note);footer.append(fButton('Начать →',()=>{s.step=1;renderFlagship()},'focus-main'));}
else if(s.step===1){eyebrow('01 · ВЕРНУТЬСЯ В МОМЕНТ');heading('Сейчас ты здесь','Не нужно менять дыхание. Найди глазами одну вещь вокруг, услышь один звук и почувствуй опору под ногами или телом. Нажми на то, что удалось заметить.');let orb=document.createElement('div');orb.className='focus-orbit';orb.innerHTML='<span>здесь<br>и сейчас</span>';body.append(orb);let options=document.createElement('div');options.className='focus-notices';[['see','Вижу предмет'],['hear','Слышу звук'],['feel','Чувствую опору']].forEach(([v,l])=>options.append(fButton((s.noticed.includes(v)?'✓ ':'○ ')+l,()=>{if(!s.noticed.includes(v))s.noticed.push(v);renderFlagship()},'focus-notice'+(s.noticed.includes(v)?' selected':''))));body.append(options);let note=document.createElement('p');note.className='focus-privacy';note.textContent='Можно просто прочитать и двигаться дальше. Если внимание к телу неприятно, пропусти этот шаг.';body.append(note);footer.append(fButton('Назад',()=>{s.step=0;renderFlagship()},'focus-back'),fButton('Продолжить →',()=>{s.step=2;renderFlagship()},'focus-main'));}
else if(s.step===2){eyebrow('02 · ОТДЕЛИТЬ СОБЫТИЕ ОТ МЫСЛИ');heading('Две разные вещи','Попробуй разделить то, что произошло, и то, что подумалось после. Это не проверка правильности твоих чувств. Поля можно оставить пустыми.');let grid=document.createElement('div');grid.className='focus-write-grid';[['fact','Что было сказано или сделано?','Например: «Руководитель повысил голос и попросил переделать отчёт»'],['thought','Какая мысль у меня об этом появилась?','Например: «Наверное, я ни на что не способна или не способен»']].forEach(([key,label,ph])=>{let wrap=document.createElement('label');wrap.textContent=label;let ta=document.createElement('textarea');ta.placeholder=ph;ta.maxLength=400;ta.value=s[key];ta.oninput=()=>s[key]=ta.value;wrap.append(ta);grid.append(wrap)});body.append(grid);let callout=document.createElement('div');callout.className='focus-callout';callout.textContent='Чувства реальны. Мысль о себе — не всегда факт. Необязательно находить объяснение прямо сейчас.';body.append(callout);footer.append(fButton('Назад',()=>{s.step=1;renderFlagship()},'focus-back'),fButton('Продолжить →',()=>{s.step=3;renderFlagship()},'focus-main'));}
else if(s.step===3){eyebrow('03 · ОДИН СЛЕДУЮЩИЙ ШАГ');heading('Что сейчас подойдёт?','Выбери действие, которое зависит от тебя. Оно может быть маленьким и не обязано решать весь конфликт.');let cards=document.createElement('div');cards.className='focus-action-grid';Object.entries(focusActions).forEach(([key,a])=>{let b=fButton('',()=>{s.action=key;renderFlagship()},'focus-action'+(s.action===key?' selected':''));let title=document.createElement('strong');title.textContent=a.title;let desc=document.createElement('small');desc.textContent=a.hint;b.append(title,desc);cards.append(b)});body.append(cards);if(s.action){let preview=document.createElement('div');preview.className='focus-phrase';preview.innerHTML='<span>ВОЗМОЖНАЯ ФРАЗА</span><p></p>';preview.querySelector('p').textContent=focusActions[s.action].detail;body.append(preview)}let q=document.createElement('h3');q.textContent='Как сейчас, по той же шкале?';body.append(q);let scale=document.createElement('div');scale.className='focus-scale';[1,2,3,4].forEach(n=>scale.append(fButton(String(n),()=>{s.after=n;renderFlagship()},'focus-scale-button'+(s.after===n?' selected':''))));body.append(scale);body.append(fButton('Не хочу оценивать',()=>{s.after=-1;renderFlagship()},'focus-skip'+(s.after===-1?' selected':'')));footer.append(fButton('Назад',()=>{s.step=2;renderFlagship()},'focus-back'),fButton('Завершить и сохранить →',finishFlagship,'focus-main'));}
focusOverlay.append(panel)}
function finishFlagship(){if(!focus)return;const s=focus;if(!s.action){focusOverlay.querySelector('.focus-action-grid')?.scrollIntoView({behavior:'smooth',block:'center'});return}if(!s.after){focusOverlay.querySelector('.focus-scale:last-of-type')?.scrollIntoView({behavior:'smooth',block:'center'});return}const outcome=s.before<1||s.after<0?'unrated':s.after<s.before?'better':s.after>s.before?'worse':'same';let all=history();all.push({day:todayKey(),practice:'flagship',outcome,source:s.source,action:s.action,at:new Date().toISOString()});save(all.slice(-365));s.completed=true;renderFlagship();focusOverlay.querySelector('.focus-panel').scrollTop=0;if(typeof checkin!=='undefined'&&checkin.practice==='flagship'){checkin.phase='followup';add(outcome==='unrated'?'Практика пройдена в твоём темпе. Хочешь рассказать ещё или закончить?':outcome==='better'?'Отмечено, что стало немного легче. Хочешь остановиться или рассказать, какой шаг оказался выбран?':outcome==='worse'?'Похоже, сейчас стало тяжелее. Остановимся. Можно обратиться к человеку рядом или выбрать другую поддержку.':'Спасибо за оценку результата. Хочешь рассказать ещё или закончить?');choices([['Расскажу ещё','talk'],['Закончить','finish']])}}
focusOverlay.addEventListener('click',e=>{if(e.target===focusOverlay)closeFlagship()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!focusOverlay.hidden)closeFlagship()});
